const API_URL = process.env.API_URL ?? "http://localhost:4000";

async function request<T>(
  path: string,
  init?: RequestInit,
  cookie?: string
): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, {
    ...init,
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      ...(cookie ? { cookie } : {}),
      ...init?.headers,
    },
  });

  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.message ?? `Request failed (${res.status})`);
  }

  return (await res.json()) as T;
}

export interface User {
  id: string;
  name: string;
  email: string;
}

export const authApi = {
  signup: (input: { name: string; email: string; password: string }) =>
    request<User>("/auth/signup", {
      method: "POST",
      body: JSON.stringify(input),
    }),
  login: (input: { email: string; password: string }) =>
    request<User>("/auth/login", {
      method: "POST",
      body: JSON.stringify(input),
    }),
  logout: (cookie?: string) =>
    request<{ message: string }>("/auth/logout", undefined, cookie),
  me: (cookie?: string) => request<User>("/auth/me", undefined, cookie),
};

import { z } from "zod";

export const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});

export const signupSchema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
  password: z.string().min(8),
});

export type LoginInput = z.infer<typeof loginSchema>;
export type SignupInput = z.infer<typeof signupSchema>;

import type { ActionFunctionArgs } from "@remix-run/node";
import { json, redirect } from "@remix-run/node";
import { Form, useActionData } from "@remix-run/react";
import { authApi } from "~/lib/auth/api";
import { loginSchema } from "~/lib/auth/validation";

export async function action({ request }: ActionFunctionArgs) {
  const formData = await request.formData();
  const parsed = loginSchema.safeParse({
    email: formData.get("email"),
    password: formData.get("password"),
  });

  if (!parsed.success) {
    return json({ error: "Invalid credentials" }, { status: 400 });
  }

  try {
    await authApi.login(parsed.data);
    return redirect("/");
  } catch (error) {
    return json({ error: (error as Error).message }, { status: 401 });
  }
}

export default function Login() {
  const actionData = useActionData<typeof action>();
  return (
    <Form method="post">
      {actionData?.error ? <p>{actionData.error}</p> : null}
      <input type="email" name="email" required />
      <input type="password" name="password" required />
      <button type="submit">Log in</button>
    </Form>
  );
}
